/* Links do porquê de Cárie (Rafael 25/11/2026): afirmação que precisa de explicação. t = trecho exato do texto do site. */
(function(){ var B = window.BANCOS && window.BANCOS.carie; if (!B) return;
  var FK = 'Fejerskov & Kidd, Cárie Dentária: a doença e seu tratamento clínico';
  var MS = 'Ministério da Saúde, Saúde Bucal no SUS (2018); Guia de recomendações para o uso de fluoretos no Brasil (2009)';
  var MM = 'Marsh & Martin, Microbiologia Oral';
  var TOR = 'Tortora, Funke & Case, Microbiologia';
  var ROB = 'Kumar, Abbas & Aster, Robbins Patologia Básica; Brasileiro Filho, Bogliolo Patologia Geral';
  var KAT = 'Katchburian & Arana, Histologia e Embriologia Oral';
  var OMS = 'OMS, Sugars and dental caries: WHO technical note (2025); OMS, Guideline: sugars intake for adults and children (2015)';
  var STE = 'Stephan RM, J Am Dent Assoc 1940;27:718-723; Fejerskov & Kidd, Cárie Dentária';
  var NEV = 'Neville et al., Patologia Oral e Maxilofacial, 4ª ed.';
  var CAR = 'Newman et al., Carranza Periodontia Clínica';
  B.porques = (B.porques || []).concat([

  /* ---------- Resumo: Cárie, o essencial ---------- */
  { t: "dente + biofilme + açúcar + TEMPO", p: "Nenhum fator sozinho faz a lesão. O biofilme só produz ácido quando recebe açúcar, o ácido só dissolve o esmalte se encostar no dente, e uma única queda de pH é desfeita pela saliva em minutos. A lesão visível só aparece quando esse ciclo se repete por semanas ou meses, porque a perda de mineral precisa vencer a remineralização muitas vezes seguidas. Por isso Newbrun acrescentou o tempo aos três círculos de Keyes. Ex.: um adolescente de Petrópolis que toma refrigerante na escola todo dia só vai mostrar mancha branca depois de alguns meses desse hábito, não na primeira semana.", fonte: FK },
  { t: "Streptococcus mutans inicia a lesão em esmalte", p: "O S. mutans é acidogênico (faz ácido lático rápido a partir do açúcar) e acidúrico (continua vivo e ativo em pH baixo). Além disso usa a sacarose para fabricar glucanos, que o prendem na superfície lisa do esmalte. Essas três armas fazem dele o principal associado à fase inicial, quando a lesão ainda está no esmalte. Ex.: na mancha branca recém-surgida perto da gengiva de uma criança que come bala todo dia, o S. mutans costuma estar em número alto no biofilme.", fonte: MM },
  { t: "lactobacilos aparecem mais na progressão", p: "Os lactobacilos aderem mal ao esmalte liso, então quase não conseguem iniciar a lesão. Eles precisam de um lugar retentivo e já ácido, como a cavidade aberta e a dentina amolecida, onde ficam presos e protegidos. Lá são muito acidúricos e mantêm o pH baixo, ajudando a lesão a avançar. Ex.: numa cavidade grande de cárie no 46, a dentina amolecida retirada com cureta tem muito lactobacilo, enquanto na mancha branca inicial ele é raro.", fonte: MM },
  { t: "Sacarose é o açúcar mais cariogênico", p: "A sacarose é fermentada em ácido tão rápido quanto a glicose, mas tem um extra: a ligação entre glicose e frutose dá energia para as glicosiltransferases do S. mutans montarem glucanos fora da célula. Esses glucanos colam as bactérias no dente e deixam o biofilme mais grosso e poroso, então o ácido fica mais tempo encostado no esmalte. Ex.: um paciente que troca o açúcar do café por adoçante com xilitol corta a fonte de ácido e também a 'cola' do biofilme.", fonte: FK },
  { t: "pH crítico do esmalte ≈ 5,5 (fluorapatita ≈ 4,5)", p: "O pH crítico é o ponto em que a saliva e o líquido do biofilme deixam de ter cálcio e fosfato suficientes para manter o cristal inteiro. Abaixo dele, o cristal começa a soltar íons para o meio. A hidroxiapatita tem uma hidroxila que reage com o ácido, por isso dissolve a partir de 5,5. Na fluorapatita o flúor ocupa esse lugar e deixa o cristal mais estável, e ele só começa a dissolver por volta de 4,5. Ex.: depois de um gole de suco o pH do biofilme vai a 5,0: a hidroxiapatita perde mineral, mas a camada com fluorapatita ainda resiste.", fonte: FK },
  { t: "pH cai em minutos e volta em 30 a 40 min", p: "Quando chega açúcar, as bactérias do biofilme o fermentam quase na hora e o ácido lático se acumula, então o pH despenca em 2 a 5 minutos. A volta é mais lenta porque depende da saliva entrar no biofilme, trazer o bicarbonato (tampão) e levar o ácido embora. Esse desenho foi medido por Stephan e ficou conhecido como Curva de Stephan. Ex.: um aluno que come um bombom no intervalo das 10h passa mais ou menos até 10h40 com o esmalte em desmineralização.", fonte: STE },
  { t: "Frequência pesa mais que quantidade", p: "Cada vez que o açúcar entra, o pH cai abaixo do crítico e fica lá por uns 30 a 40 minutos, não importa se foi um pedaço pequeno ou grande. Então o que conta é quantas vezes por dia o dente fica nesse tempo de ataque. Com poucas exposições, a saliva tem horas para remineralizar entre elas; com muitas, o esmalte quase não tem tempo de recuperar. Ex.: comer uma barra de chocolate inteira de sobremesa faz menos estrago que comer o mesmo chocolate em quadradinhos ao longo da tarde.", fonte: STE },
  { t: "Boca seca = mais cárie", p: "A saliva é a defesa natural do dente: lava o açúcar, traz o bicarbonato que neutraliza o ácido e repõe cálcio e fosfato para a remineralização. Com fluxo salivar baixo, o açúcar fica mais tempo no dente e o pH demora muito mais para voltar, então cada exposição vira um ataque bem mais longo. Ex.: uma senhora que usa vários antidepressivos e anti-hipertensivos (que secam a boca) começa a ter cárie na raiz dos dentes mesmo sem ter mudado a dieta.", fonte: FK },

  /* ---------- Resumo: Flúor e lesões ---------- */
  { t: "Flúor age principalmente de forma tópica", p: "O flúor protege quando está DISSOLVIDO na saliva e no biofilme na hora em que o pH cai. Ali ele freia a perda de mineral e, quando o pH sobe, ajuda o cálcio e o fosfato a voltarem ao esmalte já como fluorapatita. O flúor engolido e incorporado ao dente durante a formação dá pouca proteção extra. Por isso o importante é ter flúor na boca várias vezes ao dia, em baixa concentração. Ex.: escovar com dentifrício fluoretado antes de dormir e não enxaguar com muita água deixa flúor na boca durante a noite.", fonte: FK },
  { t: "fluorapatita, mais resistente ao ácido", p: "Na hidroxiapatita existe uma hidroxila (OH) na estrutura que se liga ao H+ do ácido e facilita a dissolução. Quando o fluoreto toma o lugar dessa hidroxila, o cristal fica mais compacto e estável, e precisa de um meio bem mais ácido (cerca de pH 4,5) para começar a se desfazer. Ex.: no mesmo copo de refrigerante, a camada de esmalte que recebeu flúor da pasta perde menos mineral que a camada sem flúor.", fonte: FK },
  { t: "Excesso de flúor ingerido na formação do esmalte", p: "Enquanto o esmalte está se formando, os ameloblastos precisam retirar proteínas da matriz para o cristal crescer. Flúor demais no sangue nessa fase atrapalha os ameloblastos, e o esmalte fica com mais proteína e mais poros, que aparecem como manchas brancas opacas (fluorose). Depois que o dente está formado, engolir flúor já não causa fluorose. Ex.: uma criança de 2 anos de Petrópolis que come pasta de dente da escova acumula flúor demais e pode ter os incisivos permanentes nascendo com manchas brancas.", fonte: MS },
  { t: "Mancha branca opaca e rugosa = lesão ativa e reversível", p: "A mancha branca aparece porque o ácido tirou mineral logo abaixo da superfície e deixou o esmalte poroso; os poros cheios de ar ou água desviam a luz e o dente fica branco giz. Quando é opaca e rugosa, a superfície ainda está sendo atacada pelo biofilme (lesão ativa). Como a camada de cima continua inteira (não cavitada), saliva e flúor ainda conseguem repor mineral, por isso é reversível ou ao menos pode parar. Ex.: um paciente que tirou o aparelho ortodôntico com manchas brancas em volta dos bráquetes melhora com escovação caprichada e dentifrício fluoretado.", fonte: FK },
  { t: "Brilhante, lisa e dura", p: "Quando o biofilme deixa de ficar parado sobre a lesão, a superfície é polida pela escova e pela mastigação e recebe mineral da saliva. A camada de fora fica lisa e reflete a luz (brilho), e a sonda não engancha (dura). É uma cicatriz de uma lesão que parou: não precisa de broca. Ex.: um adulto com uma mancha branca brilhante e lisa na vestibular de um pré-molar, longe da gengiva, tem uma lesão inativa antiga, só para acompanhar.", fonte: FK },
  { t: "Lesão não cavitada se trata sem broca", p: "Na lesão não cavitada a superfície do esmalte ainda existe, então o biofilme pode ser removido pela escova e o flúor consegue entrar. Tirando a causa (biofilme parado e açúcar frequente), a lesão para e pode remineralizar. Furar com broca destruiria esmalte sadio e começaria o ciclo restaurador, que sempre tira mais dente a cada troca. Ex.: na mancha branca ativa da cervical de um molar, o tratamento é ensinar escovação, diminuir a frequência de açúcar e usar flúor, sem restauração.", fonte: FK },
  { t: "Fóssulas e fissuras são os locais de maior risco", p: "O fundo da fissura é mais estreito que a cerda da escova, então o biofilme ali fica protegido da limpeza e da saliva, sempre maduro e com mais anaeróbios. Nos molares que acabaram de nascer, a face oclusal ainda fica abaixo do plano da mastigação e nem se 'autolimpa'. Por isso a cárie de fóssulas e fissuras é a mais comum em crianças. Ex.: o primeiro molar permanente, que nasce por volta dos 6 anos, é o dente que mais tem cárie na oclusal em escolares.", fonte: FK },
  { t: "selante fecha esse nicho", p: "O selante é uma resina fluida que entra na fissura e endurece, deixando a face oclusal mais rasa e lisa. Sem o 'buraco' onde o biofilme se escondia, a escova consegue limpar e a sacarose não fica parada no fundo. Enquanto estiver retido, ele corta o acúmulo de biofilme no lugar de maior risco. Ex.: numa criança de 7 anos com risco alto de cárie, selar o primeiro molar permanente logo depois que ele erupciona protege justamente a área que mais tem cárie.", fonte: MS },

  /* ---------- Etiologia ---------- */
  { t: "P. gingivalis é periodontal", p: "A Porphyromonas gingivalis é anaeróbia estrita e proteolítica: ela se alimenta de proteínas e precisa de lugar sem oxigênio, o que ela encontra no sulco e na bolsa periodontal, abaixo da gengiva. Ela não fermenta açúcar para fazer ácido, então não tem papel na cárie. O que ela faz é destruir tecido periodontal com suas enzimas e seu LPS. Ex.: numa bolsa de 6 mm de um fumante com periodontite, a P. gingivalis aparece em grande número, enquanto na mancha branca de esmalte ela praticamente não existe.", fonte: MM },
  { t: "precisam agir juntos por tempo suficiente", p: "Um dente suscetível, um biofilme com bactérias acidogênicas e açúcar na dieta não fazem cárie se aparecerem separados ou por pouco tempo. A lesão é a soma de muitos ciclos de queda de pH, e a saliva desfaz os primeiros. Só quando os três se repetem juntos por semanas a perda de mineral passa a ganhar da remineralização. Ex.: um paciente que come doce só na sobremesa de domingo tem os três fatores, mas por pouco tempo, e o risco de cárie é baixo.", fonte: FK },
  { t: "glucanos insolúveis, que deixam o biofilme mais aderente e espesso", p: "As glicosiltransferases do S. mutans quebram a sacarose e encadeiam as glicoses em glucanos que não dissolvem na água. Eles funcionam como cola entre as bactérias e a película adquirida e formam uma matriz porosa. Biofilme mais grosso demora mais para receber a saliva com bicarbonato, então o ácido fica preso perto do esmalte por mais tempo. Ex.: o biofilme de quem toma café com açúcar o dia todo é mais pegajoso e grosso que o de quem não usa sacarose.", fonte: MM },
  { t: "O ácido lático é o que desmineraliza", p: "Quando a bactéria fermenta o açúcar, o produto final é principalmente ácido lático, que é forte entre os ácidos orgânicos. Ele solta H+ no líquido do biofilme, o pH cai abaixo do crítico e o H+ reage com o fosfato e a hidroxila da hidroxiapatita, tirando cálcio e fosfato do esmalte. Os glucanos só prendem e engrossam o biofilme; quem dissolve o mineral é o ácido. Ex.: sem açúcar para fermentar, um biofilme mesmo grosso produz pouco ácido lático e a desmineralização quase não acontece.", fonte: MM },
  { t: "doença biofilme-açúcar dependente e não-transmissível", p: "Quase todo mundo já tem S. mutans e outros acidogênicos na boca desde a infância, então 'pegar a bactéria' não é o que decide quem terá cárie. O que decide é o ambiente: açúcar frequente seleciona as bactérias que fazem e toleram ácido (disbiose). Por isso a cárie é tratada como doença crônica não transmissível, como a diabetes, ligada a hábitos. Ex.: dois irmãos com a mesma microbiota da mãe podem ter resultados opostos se um toma refrigerante todo dia e o outro não.", fonte: FK },
  { t: "a bactéria está em quase todo mundo", p: "Os estreptococos do grupo mutans são passados principalmente da mãe ou do cuidador para o bebê nos primeiros anos, pela saliva, e ficam na boca a vida toda. Por isso achar a bactéria na saliva não diferencia quem tem e quem não tem a doença. A diferença está na quantidade e na atividade dela, que dependem do açúcar e do biofilme parado. Ex.: um estudante de Odontologia sem nenhuma cárie também tem S. mutans no biofilme, só que em proporção baixa.", fonte: MM },

  /* ---------- Desmineralização ---------- */
  { t: "esmalte é formado principalmente por cristais de hidroxiapatita", p: "O esmalte tem cerca de 96% de mineral, quase todo hidroxiapatita, arrumada em prismas bem compactos; quase não tem água nem proteína. Esse mineral é um sal de cálcio e fosfato que só fica estável quando o meio em volta já está cheio desses íons e com pH perto do neutro. Por isso ácido dissolve o esmalte, mas a saliva normal o protege. Ex.: um dente deixado num copo de refrigerante (pH perto de 2,5) fica com a superfície amolecida em poucos dias.", fonte: KAT },
  { t: "a saliva fica subsaturada de cálcio e fosfato", p: "Normalmente a saliva tem tanto cálcio e fosfato que está 'cheia' (supersaturada) em relação ao esmalte, então o cristal não tem para onde soltar íons. Quando o pH cai, o H+ prende o fosfato e a quantidade de fosfato livre diminui; a saliva passa a ficar 'com falta' (subsaturada) e o esmalte começa a ceder íons para equilibrar. Isso é a desmineralização. Ex.: no pH 5,0 depois de um doce, o líquido do biofilme puxa cálcio e fosfato do esmalte até o pH voltar.", fonte: FK },
  { t: "Spee e Wilson são curvas de oclusão", p: "A Curva de Spee é a curvatura das cúspides vista de lado e a de Wilson é a curvatura vista de frente: as duas descrevem como os dentes se encaixam na mordida e servem para a prótese e a ortodontia. Nenhuma delas tem relação com pH ou açúcar. A curva de pH no biofilme é a Curva de Stephan. Ex.: o protético usa a Curva de Spee para montar os dentes de uma prótese total; o dentista usa a Curva de Stephan para explicar dieta ao paciente.", fonte: FK },
  { t: "o dente passa mais tempo desmineralizando do que se recuperando", p: "Cada exposição ao açúcar abre uma janela de uns 30 a 40 minutos de pH abaixo do crítico. Entre uma janela e outra, a saliva traz cálcio, fosfato e flúor e repõe o que saiu (remineralização). Se as exposições ficam muito próximas, as janelas se encostam e a soma do tempo de perda passa a ser maior que a de ganho, e a lesão cresce. Ex.: café adoçado a cada hora, das 8h às 18h, deixa o esmalte quase o dia inteiro em ataque ácido.", fonte: STE },
  { t: "SOBE e estabiliza o pH (tampão bicarbonato)", p: "O bicarbonato da saliva reage com o H+ do ácido e vira gás carbônico e água, que saem do biofilme; assim o ácido é 'gasto' e o pH sobe. Quanto mais saliva é estimulada (mastigar, por exemplo), mais bicarbonato ela tem. Algumas bactérias ainda fazem amônia a partir da ureia salivar, o que também ajuda a subir o pH. Ex.: mascar um chiclete sem açúcar depois do almoço aumenta o fluxo salivar e faz o pH voltar ao normal mais rápido.", fonte: FK },
  { t: "É a chamada cárie de radiação", p: "A radioterapia de cabeça e pescoço destrói as células das glândulas salivares que ficam no campo, e o fluxo salivar pode cair muito e para sempre. Sem saliva não há tampão, limpeza, cálcio nem fosfato, e o paciente costuma trocar a dieta por alimentos moles e adocicados. A cárie então avança rápido, muitas vezes na cervical e na incisal, lugares onde normalmente não aparece. Ex.: um paciente tratado de câncer de língua pode ter vários dentes destruídos na cervical em poucos meses se não usar flúor de alta concentração.", fonte: FK },
  { t: "Sem saliva o pH demora a voltar", p: "A volta do pH depende de saliva nova entrar no biofilme com bicarbonato e levar o ácido embora. Com xerostomia, esse 'enxágue' quase não existe, então a curva de Stephan fica com a parte de baixo muito mais longa. Cada gole de algo doce vira horas de desmineralização. Ex.: um idoso com síndrome de Sjögren que chupa bala para aliviar a boca seca acaba tendo cárie em vários dentes, porque o pH fica baixo por muito tempo.", fonte: FK },

  /* ---------- Flúor ---------- */
  { t: "O flúor é a principal ferramenta de prevenção da cárie", p: "O flúor atua no ponto central da doença: diminui a perda de mineral quando o pH cai e acelera a volta do mineral quando o pH sobe. Ele está em quase tudo que é barato e de uso diário (água fluoretada e dentifrício fluoretado), então chega a muita gente sem depender de consulta. A queda da cárie no Brasil e no mundo nas últimas décadas é atribuída principalmente a ele. Ex.: a geração de Petrópolis que cresceu com água fluoretada e pasta com flúor tem bem menos dentes cariados que a dos avós.", fonte: MS },
  { t: "ajuda a repor mineral quando o pH sobe", p: "Quando o pH volta a subir, a saliva fica de novo cheia de cálcio e fosfato e esses íons voltam para os poros da lesão. Se tiver flúor por perto, ele entra junto e forma fluorapatita, que cresce mais rápido e fica mais resistente que o cristal original. Assim o flúor acelera e melhora a remineralização. Ex.: depois de um lanche, a escovação com dentifrício fluoretado deixa flúor na saliva justamente na fase em que o pH está voltando.", fonte: FK },
  { t: "o flúor pode substituir a hidroxila da hidroxiapatita", p: "O íon fluoreto tem a mesma carga e tamanho parecido com a hidroxila (OH-) da hidroxiapatita, então cabe no mesmo lugar do cristal. Ao entrar, ele forma ligações mais fortes e deixa o cristal mais estável, que só dissolve em meio mais ácido. Essa troca acontece principalmente na superfície do esmalte, que é a parte que recebe flúor da saliva. Ex.: a camada mais externa do esmalte de um adulto que sempre usou pasta com flúor tem mais flúor que a camada de dentro.", fonte: FK },
  { t: "só se dissolve em pH mais baixo (cerca de 4,5)", p: "Para o cristal dissolver, o meio precisa estar subsaturado de seus íons. A fluorapatita é menos solúvel que a hidroxiapatita, então a saliva continua 'cheia' em relação a ela mesmo com o pH abaixo de 5,5. Só por volta de 4,5 é que ela passa a ceder íons. Na faixa entre 5,5 e 4,5, o esmalte perde hidroxiapatita mas ganha fluorapatita na superfície. Ex.: numa queda leve de pH depois de um biscoito, a superfície com flúor quase não perde mineral.", fonte: FK },
  { t: "uma das medidas mais eficazes de prevenção coletiva da cárie", p: "A água fluoretada coloca uma pequena quantidade de flúor na boca várias vezes ao dia (cada vez que a pessoa bebe ou cozinha), sem ela precisar fazer nada. Isso atinge criança, adulto e idoso, rico ou pobre, e custa poucos centavos por pessoa por ano. Estudos mostram redução importante de cárie nas cidades com fluoretação. Ex.: uma família de Petrópolis que não vai ao dentista com frequência continua recebendo flúor tópico pela água da torneira.", fonte: MS },
  { t: "para crianças, quantidade de pasta tipo grão de arroz", p: "Criança pequena ainda não sabe cuspir direito e engole boa parte da pasta. Como a fluorose depende da quantidade de flúor engolida enquanto o esmalte se forma, a recomendação é usar dentifrício fluoretado (1.000 ppm ou mais), mas em quantidade mínima: o efeito tópico fica e o risco de engolir flúor demais cai. Ex.: para uma criança de 2 anos, uma 'sujeirinha' de pasta do tamanho de um grão de arroz cru na escova, com um adulto escovando.", fonte: MS },

  /* ---------- Diagnóstico ---------- */
  { t: "secar o dente com ar", p: "A mancha branca inicial tem poros cheios de água; a água e o esmalte desviam a luz de modo parecido, então a lesão quase some com o dente molhado de saliva. Quando o ar tira a água, os poros se enchem de ar, que desvia a luz de outro jeito, e a área desmineralizada aparece branca e opaca. Por isso o exame de cárie se faz com o dente limpo e seco. Ex.: uma lesão que só aparece depois de 5 segundos de jato de ar é bem inicial; a que aparece até molhada já está mais profunda.", fonte: FK },
  { t: "geralmente longe do acúmulo de placa", p: "A lesão só fica ativa enquanto o biofilme fica parado sobre ela. Muitas lesões inativas surgiram quando o dente estava nascendo ou a gengiva cobria a área; depois a gengiva desceu, a mastigação e a escova passaram a limpar e o biofilme parou de acumular ali. Sem biofilme, a superfície foi polida e remineralizada. Ex.: uma mancha branca brilhante no meio da vestibular de um canino, que a escova alcança bem, costuma ser inativa.", fonte: FK },
  { t: "triângulo com base na junção amelodentinária em fóssulas", p: "Na fissura, o ácido entra pelas paredes laterais e segue a direção dos prismas do esmalte, que ali se abrem em leque para dentro. Por isso a lesão de esmalte já fica larga na parte funda. Quando chega à junção amelodentinária, encontra a dentina, que tem menos mineral e túbulos, e se espalha para os lados. O resultado é uma lesão pequena por fora e grande por dentro. Ex.: um molar com um pontinho escuro na fissura pode mostrar na radiografia interproximal uma lesão larga na dentina.", fonte: FK },
  { t: "Triângulo com o vértice voltado para a junção amelodentinária", p: "Na superfície lisa o biofilme fica numa área larga e o ácido entra seguindo os prismas do esmalte, que ali correm quase retos para dentro. O ataque é maior no centro da placa e menor nas bordas, então a lesão forma um cone de base larga na superfície e ponta indo em direção à dentina. Ex.: numa lesão proximal entre dois molares, a radiografia mostra um triângulo escuro no esmalte apontando para a junção amelodentinária.", fonte: FK },
  { t: "principalmente nos molares recém-erupcionados", p: "O dente que acabou de nascer tem esmalte ainda pouco maduro (menos flúor e mais poros) e passa meses abaixo do plano de oclusão, sem a limpeza natural da mastigação. As fissuras são profundas e a criança raramente escova bem lá atrás. Juntando os fatores, o risco é maior nos primeiros anos depois da erupção. Ex.: o segundo molar permanente que nasce por volta dos 12 anos costuma ser esquecido na escovação e é ótimo candidato ao selante.", fonte: FK },

  /* ---------- Saliva, dieta, prevenção ---------- */
  { t: "Durante o sono o fluxo salivar diminui", p: "A produção de saliva segue o ritmo do dia e quase para durante o sono, porque não há estímulo de mastigação nem do paladar. Sem fluxo, o açúcar que ficou na boca não é lavado e o bicarbonato não chega para neutralizar o ácido, então o pH fica baixo por horas. Ex.: criança que dorme mamando suco adoçado tem cárie justamente nos incisivos superiores, onde o líquido fica parado a noite toda.", fonte: FK },
  { t: "presente na boca no momento do desafio ácido", p: "O flúor só consegue frear a desmineralização e ajudar a remineralização se estiver dissolvido na saliva e no biofilme enquanto o pH está caindo e subindo. O flúor que ficou preso dentro do dente durante a formação não sai para a saliva. Por isso o hábito de usar flúor várias vezes ao dia em baixa dose funciona melhor que uma dose alta isolada. Ex.: um bochecho fluoretado feito uma vez por ano protege muito menos que o dentifrício fluoretado de todo dia.", fonte: FK },
  { t: "O bicarbonato da saliva ajuda a neutralizar os ácidos", p: "O bicarbonato é uma base fraca: ele recebe o H+ do ácido lático e vira ácido carbônico, que se desfaz em água e gás carbônico. Assim o ácido some do biofilme e o pH sobe. A quantidade de bicarbonato cresce quando o fluxo salivar aumenta, por isso mastigar e estimular saliva depois de comer protege. Ex.: um paciente que usa remédio que seca a boca perde boa parte desse tampão e passa a ter lesões novas mesmo sem mudar a dieta.", fonte: FK },
  { t: "aumenta a proporção de microrganismos capazes de produzir", p: "Com quedas de pH frequentes, as bactérias que não aguentam ácido crescem menos e somem aos poucos, enquanto as acidogênicas e acidúricas (como S. mutans e lactobacilos) continuam se multiplicando. É uma seleção pelo ambiente, igual à seleção natural. A comunidade muda de composição e fica mais cariogênica: isso é a disbiose da hipótese ecológica. Ex.: depois de meses de refrigerante diário, o biofilme de um adolescente tem bem mais S. mutans do que antes.", fonte: MM },
  { t: "Película adquirida → colonização microbiana → multiplicação microbiana", p: "Bactéria não gruda direto no esmalte limpo: primeiro as proteínas da saliva se prendem na superfície e formam a película adquirida, que tem os 'receptores' para a adesão. Depois os colonizadores iniciais se ligam a ela e começam a se dividir. Só então outras espécies chegam por coagregação, e a comunidade amadurece. Cada etapa prepara a seguinte, por isso a ordem não muda. Ex.: 2 horas depois da profilaxia já há película e alguns estreptococos; em 2 a 3 dias sem escovar o biofilme já está bem organizado.", fonte: MM },
  { t: "células se soltam para colonizar outros lugares", p: "Quando o biofilme fica grande demais, falta nutriente e espaço no meio dele. Por sinais químicos (quorum sensing), algumas bactérias desligam a adesão, se soltam e vão para outra superfície, como sementes. Essa dispersão faz a comunidade se espalhar pela boca. Ex.: as bactérias que saem do biofilme de um molar sem escovação acabam colonizando um dente vizinho recém-limpo.", fonte: MM },
  { t: "essas bactérias realizam fermentação homolática", p: "Quando há muito açúcar entrando, o S. mutans precisa gerar energia rápido e, sem oxigênio suficiente, transforma quase toda a glicose em ácido lático (por isso 'homo', um produto só). Com pouco açúcar, ele faz fermentação mista, com ácidos mais fracos (acético, fórmico) e etanol. O ácido lático é mais forte, por isso o excesso de açúcar derruba o pH com mais força. Ex.: logo depois de um refrigerante, o biofilme de quem tem cárie ativa tem muito ácido lático acumulado.", fonte: MM },
  { t: "sendo normalmente livre de bactérias em sua fase inicial", p: "A película adquirida se forma em segundos porque as proteínas da saliva têm afinidade química pelo cálcio e pelo fosfato do esmalte e grudam sozinhas. As bactérias só chegam depois, quando a película já existe e expõe os 'receptores' em que elas se prendem. Por isso, nos primeiros minutos após a limpeza, a película é só proteína. Ex.: logo depois da profilaxia, o esmalte já tem película, mas ainda não tem biofilme.", fonte: MM },
  { t: "expressando, por exemplo, genes de resistência a antimicrobianos", p: "Cada bactéria solta pequenas moléculas-sinal. Quando a população fica grande, a concentração desses sinais passa de um limite e liga, ao mesmo tempo, genes que só valem a pena em grupo, como os de produção de matriz, de tolerância a ácido e de defesa contra antimicrobianos. Assim o biofilme maduro resiste muito mais que a mesma bactéria solta. Ex.: um bochecho de clorexidina mata fácil estreptococos em cultura, mas pouco afeta o biofilme maduro que ficou dias sem escovação.", fonte: MM },
  { t: "reconheceu os açúcares livres como importante fator dietético", p: "Açúcares livres (os adicionados e os de mel, xarope e suco) são fermentados rápido pelas bactérias do biofilme e são a principal fonte do ácido que causa cárie. A OMS mostrou que a quantidade de cárie numa população acompanha o consumo desses açúcares, e que menos açúcar livre significa menos cárie em todas as idades. Já o açúcar 'preso' dentro da fruta inteira tem efeito bem menor. Ex.: trocar o suco de caixinha pela laranja inteira no lanche da escola diminui os açúcares livres da criança.", fonte: OMS },
  { t: "fatores sociais e comerciais influenciam os padrões de consumo alimentar", p: "A escolha do que comer não é só individual: preço, propaganda, o que a cantina vende e o tempo das famílias decidem muito. Produtos ultraprocessados cheios de açúcares livres e carboidratos fermentáveis são baratos e muito anunciados, então chegam mais em quem tem menos informação e menos acesso a alimento fresco. Por isso a OMS defende medidas coletivas (regras de rotulagem, taxas, cantina saudável) e não só orientação no consultório. Ex.: uma escola de Petrópolis que tira o refrigerante da cantina muda o consumo de todas as crianças de uma vez.", fonte: OMS },
  { t: "Escovar sem mudar a dieta não resolve", p: "A escova tira o biofilme uma ou duas vezes por dia, mas ele volta a se formar em horas. Se o açúcar continua chegando muitas vezes ao dia, o biofilme que se refaz entre as escovações volta a produzir ácido a cada exposição. A doença é movida pelo açúcar frequente, então controlar só o biofilme deixa a causa principal ativa. Ex.: um aluno que escova depois de cada refrigerante mas toma cinco por dia continua tendo várias quedas de pH antes de escovar.", fonte: OMS },
  { t: "o risco cariogênico não depende exclusivamente da quantidade total", p: "Pela curva de Stephan, cada exposição ao açúcar abre uma janela de pH baixo, não importa o tamanho da porção. Duas pessoas que comem a mesma quantidade de açúcar por dia podem ter riscos bem diferentes conforme a forma de comer: tudo de uma vez ou espalhado ao longo do dia. Por isso a orientação de dieta pergunta 'quantas vezes', e não só 'quanto'. Ex.: a paciente que toma cinco cafezinhos adoçados no trabalho tem mais risco que outra que põe o mesmo açúcar num café só.", fonte: STE },
  { t: "substituição progressiva de bactérias aeróbias por anaeróbias", p: "Os primeiros colonizadores (estreptococos) toleram oxigênio e o consomem enquanto respiram e crescem. Conforme o biofilme engrossa, o oxigênio não chega às camadas de baixo, que ficam pobres em oxigênio. Isso cria lugar para as anaeróbias, que só crescem assim. A troca é aos poucos, por isso é chamada sucessão microbiana. Ex.: na gengivite experimental, depois de 2 a 3 semanas sem escovar aparecem anaeróbios como Fusobacterium e espiroquetas que não existiam no primeiro dia.", fonte: MM },

  /* ---------- Biofilme e microbiologia (SM2 e AV) ---------- */
  { t: "o fungo vive no solo", p: "O Paracoccidioides brasiliensis vive na terra de áreas rurais e úmidas na forma de bolor (com hifas), que solta esporos no ar quando o solo é mexido. A pessoa se infecta respirando esses esporos, primeiro no pulmão, e depois o fungo pode ir para a boca. Por isso a doença aparece em quem trabalha na lavoura, principalmente homens adultos que fumam. Ex.: um lavrador de 50 anos da zona rural de Petrópolis com úlcera de pontilhado vermelho na gengiva tem que ter a paracoccidioidomicose na lista.", fonte: NEV },
  { t: "contribui para a incorporação de colonizadores secundários", p: "Os colonizadores secundários não têm receptores para a película adquirida, então não conseguem grudar direto no dente. Eles se prendem às bactérias que já estão lá, por ligações específicas entre proteínas de superfície de uma e açúcares da outra (coagregação). Assim, cada camada nova depende da anterior e o biofilme fica mais diverso. Ex.: o Fusobacterium só entra no biofilme depois que os estreptococos e o Actinomyces já estão presos ao dente.", fonte: MM },
  { t: "Organismos-ponte podem conectar grupos com diferentes afinidades de adesão", p: "Algumas bactérias têm receptores tanto para os colonizadores iniciais quanto para os tardios. Elas grudam nos estreptococos de um lado e oferecem lugar para os anaeróbios do outro, como uma ponte. Sem elas, muitas espécies tardias não teriam onde se prender. O exemplo clássico é o Fusobacterium nucleatum. Ex.: no biofilme subgengival, a P. gingivalis só se fixa bem quando já há Fusobacterium ligando ela aos colonizadores iniciais.", fonte: MM },
  { t: "o fundo tem menos oxigênio e acumula ácido", p: "A matriz de polissacarídeos e as próprias bactérias funcionam como uma esponja grossa: as substâncias entram e saem devagar. O oxigênio é consumido pelas bactérias de cima antes de chegar ao fundo, e o ácido lático produzido lá embaixo demora para sair e para ser neutralizado pela saliva. Por isso a camada encostada no dente é a mais ácida e a mais pobre em oxigênio. Ex.: no biofilme grosso de uma fissura, o pH junto ao esmalte fica mais baixo do que na superfície do biofilme.", fonte: MM },
  { t: "nutriente acaba, nascem tantas quanto morrem", p: "No começo há comida de sobra e as bactérias se dividem sem parar (fase exponencial). Com o tempo o nutriente diminui e os resíduos tóxicos se acumulam, então a velocidade de divisão cai até igualar a de morte. O número total fica parado: é a fase estacionária. Ex.: num tubo de cultura de S. mutans com açúcar, depois de umas horas a turvação para de aumentar porque o açúcar acabou e o ácido acumulou.", fonte: TOR },
  { t: "a população dobra a cada geração", p: "A bactéria se multiplica por fissão binária: uma vira duas, duas viram quatro, e assim por diante. Se não falta nada, cada divisão leva o mesmo tempo (tempo de geração), então a população cresce em progressão geométrica, a curva 'exponencial'. Ex.: com tempo de geração de 20 minutos, 1 bactéria vira mais de 1.000 em pouco mais de 3 horas, por isso contaminação em fase exponencial preocupa tanto.", fonte: TOR },
  { t: "resultante de um desequilíbrio na homeostase do biofilme dental", p: "O biofilme de quem tem boca saudável também tem bactérias acidogênicas, mas em proporção pequena e em equilíbrio com as outras. Quando o açúcar chega com frequência, o pH baixo favorece as acidúricas e a comunidade muda (disbiose): a homeostase se perde e a desmineralização passa a ganhar. A doença vem dessa mudança da própria microbiota, e não de um germe novo que chegou. Ex.: reduzindo o açúcar e escovando bem, o biofilme volta a ter mais espécies 'boas' e a lesão para.", fonte: MM },
  { t: "o antisséptico mal penetra", p: "No biofilme maduro as bactérias ficam dentro de uma matriz grossa de polissacarídeos que segura o produto na superfície e atrasa a entrada dele. As células do fundo ainda crescem devagar e ligam genes de defesa, o que as deixa mais tolerantes. Por isso a concentração que mata a bactéria solta não chega a matar a de dentro do biofilme. Ex.: o enxaguante usado sem escovação deixa o biofilme da cervical praticamente intacto; depois da escova e do fio, ele age bem melhor no que sobrou.", fonte: MM },
  { t: "retendo o corante cristal violeta no Método de Gram", p: "No Gram, o cristal violeta e o iodo formam um complexo grande dentro da célula. Quando entra o álcool, a parede grossa de peptidoglicano das Gram-positivas se desidrata e aperta, prendendo o complexo lá dentro; a célula fica roxa. Na Gram-negativa a parede é fina e o álcool dissolve a membrana externa, então o violeta sai e ela pega a cor rosa do contracorante. Ex.: o S. mutans aparece roxo no microscópio; a P. gingivalis aparece rosa.", fonte: TOR },
  { t: "O gênero Streptococcus é predominante na cavidade bucal", p: "Os estreptococos têm proteínas de superfície que se ligam muito bem às proteínas da saliva e da película adquirida, toleram oxigênio e usam os açúcares da dieta e da saliva. Assim, são os primeiros a ocupar o dente e as mucosas e formam a maior parte dos colonizadores iniciais. Ex.: num esfregaço de biofilme de 4 horas, a maioria das bactérias são cocos Gram-positivos em cadeia, os estreptococos.", fonte: MM },
  { t: "associado ao uso de dentifrício fluoretado", p: "A escova e o fio tiram o biofilme mecanicamente, e o dentifrício fluoretado deixa flúor na saliva logo depois, justamente quando o mineral pode voltar ao esmalte. Os dois juntos atacam a causa (biofilme) e reforçam a defesa (remineralização). Ex.: um paciente com manchas brancas ativas que passa a escovar 2 vezes ao dia com pasta de 1.450 ppm de flúor costuma ver as lesões ficarem brilhantes em algumas semanas.", fonte: FK },
  { t: "é tratamento invasivo desnecessário", p: "A lesão não cavitada ainda tem superfície inteira e pode parar e remineralizar com controle do biofilme, dieta e flúor. Restaurar exige cortar esmalte sadio em volta, e toda restauração um dia precisa ser trocada, cada vez maior: é o 'ciclo restaurador'. Então furar uma lesão que pararia sozinha gasta dente à toa. Ex.: uma mancha branca ativa na cervical tratada com flúor e escovação vira inativa sem perder nenhum milímetro de esmalte.", fonte: FK },
  { t: "pode levar à perda progressiva de estrutura dentária", p: "Se o açúcar frequente e o biofilme continuam, a desmineralização ganha sempre da remineralização. A superfície do esmalte cede (cavitação), o biofilme se esconde dentro do buraco, onde a escova não alcança, e a lesão avança mais rápido na dentina, que tem menos mineral. No fim pode chegar à polpa e destruir a coroa. Ex.: uma mancha branca ignorada em uma criança pode virar, em um ou dois anos, uma cavidade com dor de pulpite.", fonte: FK },
  { t: "a lesão pode ser paralisada mudando biofilme, dieta, flúor e saliva", p: "A lesão é o resultado de um desequilíbrio entre perder e ganhar mineral. Se os fatores que puxam para a perda (biofilme parado, açúcar frequente) são controlados e os que puxam para o ganho (flúor, saliva) são reforçados, a balança vira e a lesão para. Por isso a progressão não é inevitável, mesmo sendo lenta. Ex.: um adolescente com várias manchas brancas que corta o refrigerante diário e passa a usar dentifrício fluoretado tem as lesões inativadas em poucos meses.", fonte: FK },
  { t: "o biofilme é dinâmico, com sucessão microbiana", p: "O biofilme nunca fica igual: as primeiras bactérias consomem oxigênio, produzem ácidos e mudam o ambiente, o que permite a chegada de outras espécies. Ao mesmo tempo, células se dividem, morrem e se soltam. Por isso a composição de um biofilme de horas é bem diferente da de um biofilme de semanas. Ex.: o biofilme de 1 dia é quase só de estreptococos; com 2 semanas sem escovar já tem muitos anaeróbios e espiroquetas.", fonte: MM },
  { t: "a película também é local de adesão das bactérias", p: "As proteínas da película adquirida (como as ricas em prolina e a estaterina) protegem o esmalte, segurando cálcio e fosfato perto dele. Mas essas mesmas proteínas expõem pedaços que funcionam como receptores para as adesinas dos colonizadores iniciais. Assim a película tem papel duplo: protege e serve de base para o biofilme. Ex.: o S. sanguinis gruda na película de um dente limpo poucos minutos depois da profilaxia.", fonte: MM },
  { t: "pois modificam a exposição e a capacidade de controlar", p: "Biofilme e açúcar são as causas diretas, mas quem consome mais açúcar, escova menos ou não tem flúor e dentista depende de renda, escolaridade, acesso e informação. Esses fatores sociais não dissolvem o esmalte sozinhos, mas aumentam ou diminuem a chance de os fatores diretos aparecerem e serem controlados. Por isso a cárie se concentra nos grupos mais pobres. Ex.: o jovem do caso, sem acesso ao dentista e sem saber de prevenção, tem mais dificuldade de controlar o biofilme e a dieta.", fonte: MS },
  { t: "favorecer a seleção de microrganismos acidogênicos e acidúricos", p: "Cada queda de pH funciona como um filtro: espécies sensíveis ao ácido crescem menos e as que fazem e aguentam ácido ganham espaço. Com açúcar frequente, esse filtro age várias vezes ao dia e, aos poucos, a comunidade passa a ter mais S. mutans e lactobacilos. Isso é a base da hipótese ecológica de Marsh. Ex.: o segundo paciente do caso, com sacarose frequente, tem o mesmo tanto de biofilme que o primeiro, mas um biofilme mais cariogênico.", fonte: MM },
  { t: "contribuir para a estabilidade ecológica do biofilme", p: "Se a saliva neutraliza o ácido rápido, o flúor ajuda a remineralizar e a dieta tem pouco açúcar, o pH quase não fica baixo. Sem o filtro ácido, as bactérias acidúricas não ganham vantagem e a comunidade continua equilibrada, mesmo tendo algumas espécies cariogênicas. Ex.: o primeiro paciente do caso tem biofilme e até S. mutans, mas com bom fluxo salivar e pouca sacarose não tem lesão ativa.", fonte: MM },
  { t: "não de uma bactéria que vem de fora", p: "As bactérias ligadas à cárie já fazem parte da microbiota residente de quase todo mundo. A hipótese ecológica explica que a doença surge quando o ambiente (açúcar frequente, pouca saliva) muda e essas residentes passam a dominar. Não é preciso 'pegar' um germe novo, como numa gripe. Ex.: um paciente sem cárie por anos começa a ter lesões quando passa a tomar bebida energética adoçada todo dia, sem ter tido contato com ninguém novo.", fonte: MM },
  { t: "quitina na parede e ergosterol na membrana", p: "O fungo é eucarionte e tem duas camadas de proteção: por fora, a parede rígida, feita de quitina e beta-glucanos, que dá forma e resiste à pressão; por dentro, a membrana, onde o ergosterol faz o papel que o colesterol tem nas nossas células. Como nenhum dos dois existe na célula humana, eles são alvos de antifúngicos. Ex.: a nistatina, usada no 'sapinho' por Candida, se liga ao ergosterol da membrana e abre poros que matam o fungo.", fonte: TOR },
  { t: "com nucleoide e possibilidade de plasmídeos", p: "Bactéria é procarionte: o DNA principal fica solto numa região do citoplasma chamada nucleoide, sem membrana em volta. Muitas também têm plasmídeos, pequenos DNAs circulares extras que se copiam sozinhos e podem passar de uma bactéria para outra. Ter plasmídeo não significa ter núcleo. Ex.: uma bactéria da boca que recebe um plasmídeo com gene de resistência pode passar a resistir à amoxicilina.", fonte: TOR },
  { t: "Leveduras são predominantemente unicelulares e podem se multiplicar por brotamento", p: "A levedura é um fungo de uma célula só, redonda ou oval. Para se multiplicar, ela forma um broto na parede, copia o núcleo para dentro dele e o broto cresce até se soltar; algumas espécies se dividem ao meio (fissão). Já os fungos filamentosos crescem em hifas, e o conjunto delas é o micélio. Ex.: no esfregaço de uma candidíase aparecem células ovais com brotos (leveduras) e, às vezes, filamentos (hifas).", fonte: TOR },
  { t: "peptidoglicano grosso segura o corante depois do álcool", p: "O cristal violeta entra em todas as bactérias e, com o iodo, forma um complexo grande. O álcool desidrata a parede: na Gram-positiva, as muitas camadas de peptidoglicano se fecham como uma rede apertada e o complexo não sai, então ela fica roxa. A Gram-negativa tem pouco peptidoglicano e uma membrana externa que o álcool dissolve, e perde o violeta. Ex.: se o aluno deixar o álcool tempo demais, até Gram-positivas podem descolorir e parecer rosa, um erro clássico de técnica.", fonte: TOR },
  { t: "estreptococo é em cadeia", p: "O arranjo depende de como a bactéria se divide. O estreptococo se divide sempre no mesmo plano e as células filhas ficam presas uma na outra, formando uma fileira, como colar de contas. O estafilococo se divide em planos diferentes e forma um cacho de uva. Ex.: o Streptococcus mutans aparece no Gram como cocos roxos em cadeia; o Staphylococcus aureus, como cocos roxos em cacho.", fonte: TOR },
  { t: "Espiral flexível = espiroqueta", p: "A espiroqueta tem filamentos de movimento (endoflagelos) por dentro do envoltório, entre a membrana e a parede. Quando eles giram, o corpo todo se torce e se dobra, por isso ela é flexível e anda 'saca-rolhas'. O espirilo tem flagelos por fora e corpo rígido. Ex.: o Treponema da doença periodontal é uma espiroqueta que se move girando no fluido da bolsa.", fonte: TOR },
  { t: "Ordem: etiologia (causa) → patogênese (mecanismo)", p: "A doença acontece numa sequência lógica: primeiro existe a causa (etiologia); depois a causa dispara eventos nas células e moléculas (patogênese); esses eventos mudam a forma do tecido (morfologia); e a forma alterada atrapalha a função e causa sinais e sintomas (repercussão funcional). Cada etapa depende da anterior. Ex.: na cárie, açúcar e biofilme (causa) geram ácido (mecanismo), que forma a cavidade (morfologia), que leva à dor quando chega perto da polpa (função).", fonte: ROB },
  { t: "ATP é da mitocôndria", p: "O ATP é produzido em grande quantidade na respiração celular, e a parte final dela (cadeia respiratória) acontece na membrana interna da mitocôndria. O vacúolo do fungo tem outras funções: guardar, regular o pH, controlar a água e degradar (autofagia). Ex.: uma levedura sem mitocôndria funcionando só consegue energia por fermentação, que dá muito menos ATP por glicose.", fonte: TOR },

  /* ---------- Glossário de Cárie ---------- */
  { t: "Só sai com remoção mecânica", p: "Depois de alguns dias, o biofilme está preso por glucanos e pela coagregação e protegido por uma matriz grossa. O bochecho apenas passa por cima, sem quebrar essa estrutura, e o antisséptico mal penetra. A escova e o fio rompem fisicamente a matriz e arrancam as bactérias da superfície. Ex.: um paciente que só usa enxaguante e não escova continua com biofilme maduro na cervical, que aparece corado na evidenciação.", fonte: MM },
  { t: "um dos principais patógenos da periodontite", p: "A Porphyromonas gingivalis produz enzimas (gingipaínas) que quebram proteínas da gengiva e do sistema de defesa, e seu LPS provoca inflamação forte. Ela ainda bagunça a resposta do hospedeiro, favorecendo o crescimento de outras espécies periodontais. A destruição de tecido de suporte vem dessa inflamação que não se resolve. Ex.: a P. gingivalis é encontrada em grande número nas bolsas profundas de pacientes com periodontite avançada.", fonte: CAR },
  { t: "pode causar candidíase quando a defesa cai", p: "A Candida albicans vive na boca de muita gente sem causar nada, controlada pela saliva, pela imunidade e pelas bactérias que competem com ela. Quando algum desses freios falha (antibiótico que mata as bactérias, boca seca, diabetes, prótese suja, imunidade baixa), ela cresce, forma hifas e invade a mucosa. Ex.: um idoso que dorme com a prótese total e acabou de tomar antibiótico aparece com placas brancas que saem na raspagem.", fonte: NEV },
  { t: "importante em cárie de raiz", p: "A raiz exposta é coberta por cemento e dentina, que têm menos mineral que o esmalte e dissolvem em pH mais alto (por volta de 6,2 a 6,7). O Actinomyces se prende bem a essa superfície e à película, e produz ácido. Como a superfície já é frágil, mesmo um biofilme pouco acidogênico causa lesão. Ex.: um idoso com recessão gengival e boca seca tem cárie na raiz dos dentes, onde o Actinomyces é encontrado com frequência.", fonte: MM },
  { t: "bem menos cariogênico que a sacarose", p: "A lactose é fermentada mais devagar pelas bactérias do biofilme e não serve para fazer glucanos, então produz menos ácido e não engrossa a matriz. Além disso, o leite traz cálcio, fosfato e caseína, que ajudam a proteger o esmalte. Ex.: um copo de leite puro na merenda tem efeito cariogênico baixo; já o leite com achocolatado (sacarose) é bem mais cariogênico.", fonte: FK },
  { t: "É fermentado muito devagar, por isso é pouco cariogênico", p: "Poucas bactérias da boca conseguem usar o sorbitol, e as que conseguem fazem isso lentamente. Assim, o ácido sai em quantidade pequena e a saliva consegue neutralizar antes de o pH chegar ao crítico. Por isso o chiclete 'sem açúcar' com sorbitol quase não baixa o pH. Ex.: mascar um chiclete com sorbitol depois do almoço estimula saliva sem dar uma queda de pH importante.", fonte: FK },
  { t: "Cru é pouco cariogênico; cozido e processado pode ser quebrado", p: "O grão de amido cru é fechado e a amilase da saliva quase não consegue quebrá-lo. O cozimento e o processamento abrem os grãos (gelatinizam), e aí a amilase corta o amido em maltose e glicose, que as bactérias fermentam. Alimentos processados ainda grudam nos dentes, ficando mais tempo no biofilme. Ex.: batata crua quase não faz ácido; biscoito de amido que gruda na oclusal faz.", fonte: FK },
  { t: "um efeito protetor contra a cárie", p: "Algumas bactérias do biofilme quebram a ureia da saliva e aminoácidos e liberam amônia, que é uma base. Ela neutraliza parte do ácido e ajuda o pH a voltar mais rápido depois do açúcar. Quem tem biofilme com boa produção de amônia tende a ter menos cárie. Ex.: em pacientes com pouca cárie, o pH do biofilme em repouso costuma ser mais alto, em parte por causa da amônia.", fonte: MM },
  { t: "Dissolve quando o meio fica ácido", p: "A hidroxiapatita é um sal de cálcio e fosfato com hidroxila. O H+ do ácido se liga ao fosfato e à hidroxila, tirando esses íons do cristal. Com menos íons no meio, o cristal solta mais cálcio e fosfato para tentar equilibrar, e vai se desfazendo. Ex.: o esmalte perde mineral cada vez que o pH do biofilme cai abaixo de 5,5 depois de um doce.", fonte: FK },
  { t: "Funciona como reservatório que libera flúor quando o pH cai", p: "Depois de uma aplicação de flúor concentrado (gel, verniz), forma-se uma camada de fluoreto de cálcio sobre o esmalte, protegida por proteínas e fosfato da saliva. Em pH normal ela quase não dissolve; quando o pH cai, ela solta flúor justamente na hora do ataque ácido, ajudando a formar fluorapatita. Ex.: o verniz fluoretado aplicado no consultório continua liberando flúor nos desafios ácidos dos dias seguintes.", fonte: FK },
  { t: "Não tem células, por isso não se regenera, mas pode remineralizar", p: "Os ameloblastos que formam o esmalte somem quando o dente nasce, então ninguém mais fabrica esmalte novo. O que dá para fazer é repor mineral nos cristais que perderam parte dele: cálcio e fosfato da saliva voltam aos poros quando o pH sobe, com ajuda do flúor. Um buraco (cavitação), porém, não se fecha sozinho. Ex.: uma mancha branca pode endurecer de novo; uma cavidade precisa de restauração.", fonte: KAT },
  { t: "Some depois que o dente erupciona", p: "O ameloblasto termina sua função quando o esmalte está completo: ele vira parte do epitélio reduzido do órgão do esmalte, que se desfaz quando o dente rompe a gengiva. Sem essas células, não existe mais produção de esmalte depois da erupção. Ex.: uma fratura de esmalte num incisivo de adulto nunca 'cresce de volta'; só pode ser restaurada.", fonte: KAT },
  { t: "Cada ponto a menos é 10 vezes mais ácido", p: "O pH é o logaritmo da concentração de H+ com sinal trocado: cada unidade a menos significa 10 vezes mais H+ no líquido. Por isso uma queda que parece pequena faz muita diferença para o esmalte. Ex.: um biofilme em pH 5,0 tem 100 vezes mais H+ do que em pH 7,0, o suficiente para dissolver hidroxiapatita.", fonte: FK },
  { t: "aumenta quando o fluxo de saliva aumenta", p: "As glândulas salivares secretam mais bicarbonato quando trabalham estimuladas, por exemplo ao mastigar ou sentir gosto. Por isso a saliva estimulada tem pH e capacidade tampão maiores que a saliva de repouso. Ex.: mascar chiclete sem açúcar depois de comer aumenta o fluxo e o bicarbonato, e o pH do biofilme volta mais rápido.", fonte: FK },
  { t: "Aumenta muito o risco de cárie e de candidíase", p: "A saliva limpa o açúcar, neutraliza o ácido, repõe mineral e tem anticorpos e substâncias antifúngicas. Com boca seca, tudo isso diminui: o biofilme cresce e fica ácido por mais tempo (cárie), e a Candida encontra menos competição e menos defesa (candidíase). Ex.: pacientes com síndrome de Sjögren ou que fizeram radioterapia costumam ter cárie cervical e candidíase de repetição.", fonte: FK },
  { t: "gruda no esmalte segundos após a limpeza", p: "As proteínas da saliva têm partes com carga que se atraem pelo cálcio e pelo fosfato do esmalte. Como a boca está sempre banhada de saliva, assim que a superfície é limpa essas proteínas já se depositam sobre ela. Por isso não existe dente 'totalmente limpo' por mais que alguns segundos. Ex.: logo depois do polimento na profilaxia, o esmalte já está coberto por uma película fina e sem bactérias.", fonte: MM },
  { t: "obrigatória por lei desde 1974", p: "A Lei federal 6.050, de 1974, tornou obrigatória a fluoretação da água nas cidades com estação de tratamento. A decisão veio dos estudos que mostravam grande queda de cárie nas cidades fluoretadas, com custo muito baixo por pessoa. O ajuste é feito de acordo com o clima de cada região (no Brasil, em torno de 0,7 ppm). Ex.: a água tratada que abastece Petrópolis recebe flúor por essa lei, e a vigilância sanitária confere o teor.", fonte: MS },
  { t: "enquanto o dente se forma (até uns 6 a 8 anos)", p: "Os dentes permanentes da frente terminam a formação da coroa por volta dos 6 a 8 anos; depois disso os ameloblastos não existem mais e o flúor engolido não muda o esmalte. Por isso a fluorose só acontece com excesso de flúor nessa fase. Os incisivos permanentes, mais visíveis, são os mais importantes para a estética. Ex.: um adulto que bebe muita água fluoretada não desenvolve fluorose; uma criança de 2 anos que come pasta, pode.", fonte: MS },
  { t: "A superfície fica lisa e brilhante", p: "Na erosão o ácido vem de fora (refrigerante, refluxo) e ataca a superfície de forma uniforme, sem um biofilme parado num ponto. O esmalte vai sendo removido camada por camada e polido pela língua e pela escovação, então fica liso, brilhante e às vezes com bordas arredondadas. Na cárie o ácido nasce sob o biofilme e deixa a área opaca e rugosa. Ex.: um paciente com refluxo tem a face palatina dos incisivos superiores lisa, brilhante e mais fina.", fonte: FK },
  { t: "se fixa na dentina e deixa os dentes acinzentados", p: "A tetraciclina se liga ao cálcio e entra nos tecidos que estão mineralizando naquele momento, como a dentina em formação. Ela fica presa ali e, com a luz, oxida e escurece, dando faixas cinza ou amarronzadas. Por isso não se prescreve tetraciclina para gestantes e crianças pequenas. Ex.: um adulto que tomou tetraciclina na infância tem dentes com faixas acinzentadas que não saem com clareamento comum.", fonte: NEV },
  { t: "Biofilme dentro da cavidade fica protegido", p: "Quando a superfície do esmalte desaba, forma-se um buraco onde a cerda da escova não entra. O biofilme dentro dele fica parado, sem limpeza nem saliva, e mantém o pH baixo o tempo todo. Por isso a lesão cavitada costuma precisar de restauração ou de um fechamento que permita limpar. Ex.: uma cavidade oclusal pequena no 36 continua cheia de biofilme mesmo em quem escova bem.", fonte: FK },
  { t: "Típica na cervical, em forma de cunha", p: "A abrasão vem do atrito mecânico, principalmente escova dura e escovação horizontal com força. A cervical é onde o esmalte é mais fino e a dentina fica perto, e é ali que a escova bate de frente, cavando um sulco em 'V' (cunha). Diferente da cárie, a área fica lisa e dura. Ex.: um paciente que escova com força e escova dura tem desgastes em cunha na cervical dos caninos e pré-molares.", fonte: FK },
  { t: "Sai com profilaxia, ao contrário da cárie", p: "A mancha extrínseca é pigmento grudado na película e no biofilme, por fora do esmalte, sem perda de mineral. A pasta de profilaxia remove esse depósito e a superfície volta à cor normal. A cárie é perda de mineral dentro do dente, então nada sai na profilaxia. Ex.: as manchas marrons de chá ou de clorexidina saem com taça de borracha e pasta; uma lesão de cárie escurecida continua lá.", fonte: FK },
  { t: "Junta biofilme com facilidade", p: "A região cervical fica perto da margem da gengiva, num ângulo em que a escova costuma passar mal e onde a mastigação não limpa. O biofilme fica parado ali, e é por isso que manchas brancas, gengivite e cárie de raiz aparecem tanto nessa área. Ex.: na evidenciação de placa, a faixa corada perto da gengiva dos molares é o lugar mais comum de falha da escovação.", fonte: FK },
  { t: "é a forma de flúor tópico com melhor custo-benefício", p: "O dentifrício fluoretado junta duas ações num só hábito: a escova tira o biofilme e a pasta deixa flúor na boca. É barato, usado duas vezes ao dia por quase todo mundo e não depende do dentista. Estudos mostram que ele reduz muito a cárie em todas as idades. Ex.: uma família que só compra pasta com pelo menos 1.000 ppm de flúor já tem a principal medida de prevenção em casa.", fonte: MS },
  { t: "Creme dental com flúor (1.000 a 1.500 ppm)", p: "Os estudos mostram que o efeito anticárie aparece a partir de cerca de 1.000 ppm de flúor; abaixo disso a proteção é fraca. A faixa até 1.500 ppm é segura para uso diário, desde que a criança pequena use pouca quantidade. Ex.: na embalagem do dentifrício fluoretado deve aparecer 1.000, 1.100 ou 1.450 ppm de F; pastas 'infantis' com 500 ppm protegem pouco.", fonte: MS },
  { t: "Não remove biofilme maduro sozinho", p: "O enxaguante só passa pela superfície do biofilme. Ele não quebra a matriz nem solta as bactérias presas por glucanos e coagregação, e o produto mal penetra até o fundo. Por isso o bochecho é complemento: precisa de escovação e fio dental antes. Ex.: um paciente que troca a escova pelo enxaguante continua com biofilme na cervical e gengivite.", fonte: MM },
  { t: "O exemplo clássico é o Fusobacterium nucleatum", p: "O Fusobacterium nucleatum tem várias proteínas de superfície que se ligam tanto aos colonizadores iniciais (estreptococos, Actinomyces) quanto aos tardios (como P. gingivalis). Ele aparece no biofilme justamente na fase de transição, conectando os dois grupos por coagregação. Ex.: sem Fusobacterium, a P. gingivalis tem dificuldade de se fixar no biofilme subgengival.", fonte: MM },
  { t: "segura cálcio e fosfato perto do dente", p: "A saliva é supersaturada de cálcio e fosfato; sem controle, esses íons formariam cristais em qualquer lugar (como cálculo). A estaterina se liga a eles e impede que precipitem, mas os mantém disponíveis perto do esmalte para a remineralização. Ex.: graças à estaterina, a saliva repõe mineral no esmalte depois de uma queda de pH sem formar cálculo o tempo todo.", fonte: MM },
  { t: "É mais associado à saúde que à cárie", p: "O S. sanguinis é colonizador inicial, faz pouco ácido e produz peróxido de hidrogênio, que atrapalha o crescimento do S. mutans. Biofilmes com mais S. sanguinis costumam estar em equilíbrio. Quando o açúcar frequente derruba o pH, ele perde espaço para as acidúricas. Ex.: crianças sem cárie costumam ter mais S. sanguinis em relação ao S. mutans do que crianças com muitas lesões.", fonte: MM },
  { t: "levedura a 37 °C no corpo", p: "O fungo dimórfico muda de forma conforme a temperatura. No solo, a 25 °C, cresce como bolor com hifas e solta esporos. Dentro do corpo, a 37 °C, liga outros genes e vira levedura, forma mais resistente às defesas. Por isso a biópsia mostra leveduras, nunca hifas. Ex.: no Paracoccidioides, a lâmina mostra a levedura grande com vários brotos em volta (roda de leme).", fonte: TOR },
  { t: "fica latente no gânglio do nervo trigêmeo", p: "Na primeira infecção, o HSV-1 entra pelas terminações nervosas da boca e sobe pelo nervo até o gânglio trigeminal, onde 'adormece' dentro do neurônio, fora do alcance dos anticorpos. Em situações de estresse, sol, febre ou baixa imunidade, ele desce pelo nervo e causa o herpes labial no mesmo lugar. Como é vírus e não bactéria, não aparece no Método de Gram e antibiótico não trata. Ex.: um aluno que sempre tem herpes labial na semana de provas está tendo reativação do vírus latente.", fonte: NEV },
  { t: "É o alvo de antifúngicos como nistatina e fluconazol", p: "Como o ergosterol só existe na membrana do fungo (nas nossas células é o colesterol), os remédios que mexem nele atingem o fungo e poupam o paciente. A nistatina se liga ao ergosterol e abre poros na membrana; o fluconazol impede a fabricação de ergosterol. Ex.: uma candidíase pseudomembranosa por Candida albicans em idoso com prótese melhora com nistatina em suspensão.", fonte: TOR },
  { t: "Pode levar genes de resistência a antibiótico", p: "O plasmídeo se copia independentemente do cromossomo e pode ser passado de uma bactéria para outra (conjugação), até de espécies diferentes. Se ele carrega um gene que destrói ou expulsa o antibiótico, a bactéria que o recebe passa a resistir. Isso espalha resistência rápido, e dentro do biofilme, com as bactérias coladas, essa troca é ainda mais fácil. Ex.: uso de antibiótico sem necessidade seleciona bactérias com plasmídeos de resistência na boca e no intestino.", fonte: TOR },
  { t: "O álcool tira o violeta e ela fica ROSA", p: "A Gram-negativa tem uma membrana externa cheia de lipídios por cima de uma camada fina de peptidoglicano. O álcool dissolve essa membrana e a parede fina não segura o complexo violeta-iodo, que sai. A célula fica sem cor até receber o contracorante (safranina), que a pinta de rosa. Ex.: a E. coli e a P. gingivalis aparecem rosa na lâmina de Gram.", fonte: TOR },
  { t: "Causa febre e inflamação", p: "O LPS é reconhecido pelas células de defesa por um receptor próprio (TLR4), que dispara a liberação de citocinas como IL-1 e TNF. Essas citocinas dilatam vasos, chamam neutrófilos e, no cérebro, aumentam a temperatura (febre). Na boca, o LPS das Gram-negativas do biofilme mantém a inflamação da gengiva. Ex.: na periodontite, o LPS de bactérias Gram-negativas ajuda a manter a inflamação que destrói o osso.", fonte: TOR },
  { t: "Não é uma fase da curva de crescimento", p: "A curva de crescimento descreve o número de células numa cultura ao longo do tempo: lag, exponencial, estacionária e declínio. Esporulação é outra coisa: é a forma de resistência que só algumas bactérias (Bacillus, Clostridium) fazem quando o meio fica ruim, e pode até acontecer na fase estacionária, mas não é uma fase. Ex.: o S. mutans nunca esporula; o Clostridium sim, por isso a esterilização precisa matar esporos.", fonte: TOR },
  { t: "É o padrão-ouro para o diagnóstico de lesões", p: "Na biópsia o patologista vê as próprias células e a arquitetura do tecido no microscópio, o que mostra se a lesão é inflamação, infecção, benigna ou maligna. O aspecto clínico pode enganar, porque lesões diferentes se parecem. Por isso o laudo histopatológico é o que fecha o diagnóstico. Ex.: uma úlcera que não cicatriza em 15 dias pode parecer trauma, mas só a biópsia confirma se é carcinoma.", fonte: NEV },
  { t: "Só sai com raspagem profissional", p: "O cálculo é biofilme que mineralizou com cálcio e fosfato da saliva e ficou duro como pedra, preso na superfície do dente. A escova e o fio não conseguem quebrar esse depósito, então é preciso cureta ou ultrassom no consultório. Ex.: o tártaro na lingual dos incisivos inferiores, perto da saída das glândulas, só sai com raspagem.", fonte: CAR },

  /* ---------- Complementos ---------- */
  { t: "O xilitol não é fermentado pelo S. mutans", p: "O S. mutans até leva o xilitol para dentro da célula, mas não tem as enzimas para quebrá-lo e gerar energia; ainda gasta energia tentando expulsá-lo. Sem fermentação não há ácido lático, então o pH do biofilme não cai abaixo do crítico. Por isso o xilitol é considerado não cariogênico e é usado em chicletes e balas 'sem açúcar'. Ex.: mascar chiclete com xilitol depois do lanche estimula saliva sem dar queda de pH.", fonte: FK },
  { t: "faz o pH do biofilme cair abaixo do crítico", p: "As bactérias acidogênicas do biofilme fermentam o açúcar em poucos minutos e soltam ácido lático no líquido do biofilme. Como o biofilme segura esse ácido perto do dente e a saliva demora a chegar, o pH passa do crítico (cerca de 5,5) em quase toda exposição, mesmo pequena. É a parte de baixo da Curva de Stephan. Ex.: um único gole de refrigerante já derruba o pH do biofilme na cervical abaixo de 5,5 por alguns minutos.", fonte: STE },
  { t: "Ter S. mutans não é ter a doença", p: "Quase todo mundo carrega S. mutans no biofilme desde a infância. A doença só aparece quando o açúcar frequente e o biofilme parado fazem a desmineralização ganhar da remineralização por muito tempo. Achar a bactéria mostra só que ela está ali, não que a balança desequilibrou. O diagnóstico de cárie é clínico, pela lesão (mancha branca ativa, cavitação). Ex.: um estudante sem nenhuma lesão pode ter S. mutans na saliva e não ter a doença cárie.", fonte: MM },
  ]);
})();
